    context.globalAlpha = alpha;
    this.ready = ready;
    this.tileClipContexts_ = tileClipContexts;

    // only draw the cached tile‐image layer when not in 'vector' mode;
    // in vector mode we've just painted fills/strokes ourselves
    if (layer.getRenderMode() !== 'vector') {
      super.postRender(context, frameState);
